validate_doc_update:
function(newDoc, oldDoc, userCtx){
  if (newDoc._deleted) { return; }
  if (newDoc.type !== 'lectura_medidor') { return; }
  if (!newDoc.medidor_id) {
    throw({forbidden: 'falta medidor_id'});
  }
  if (typeof newDoc.valor_m3 !== 'number' || isNaN(newDoc.valor_m3)) {
    throw({forbidden: 'valor_m3 tiene que ser un número'});
  }
  if (newDoc.valor_m3 < 0) {
    throw({forbidden: 'un medidor no puede marcar negativo: ' + newDoc.valor_m3});
  }
  if (oldDoc && typeof oldDoc.valor_m3 === 'number' && newDoc.valor_m3 < oldDoc.valor_m3) {
    throw({forbidden: 'un medidor no retrocede: ya marcaba ' + oldDoc.valor_m3 + ' y querés grabar ' + newDoc.valor_m3});
  }
}
